-- 1. Penambahan Kolom Baru ke Tabel public.dkpp_pegawai_nip
ALTER TABLE public.dkpp_pegawai_nip
ADD COLUMN IF NOT EXISTS tempat_lahir VARCHAR(100),
ADD COLUMN IF NOT EXISTS tanggal_lahir DATE,
ADD COLUMN IF NOT EXISTS tanggal_lahir_str VARCHAR(100),
ADD COLUMN IF NOT EXISTS pangkat VARCHAR(100),
ADD COLUMN IF NOT EXISTS tmt_golongan VARCHAR(50),
ADD COLUMN IF NOT EXISTS tmt_jabatan VARCHAR(50),
ADD COLUMN IF NOT EXISTS esselon VARCHAR(50),
ADD COLUMN IF NOT EXISTS pendidikan VARCHAR(100),
ADD COLUMN IF NOT EXISTS diklat VARCHAR(150),
ADD COLUMN IF NOT EXISTS kategori_pegawai VARCHAR(50),
ADD COLUMN IF NOT EXISTS keterangan TEXT;

-- 2. Buat Index Tambahan untuk Kolom Baru
CREATE INDEX IF NOT EXISTS idx_dkpp_pegawai_nip_kategori ON public.dkpp_pegawai_nip (kategori_pegawai);
CREATE INDEX IF NOT EXISTS idx_dkpp_pegawai_nip_tgl_lahir ON public.dkpp_pegawai_nip (tanggal_lahir);

