ON CONFLICT (nip) DO UPDATE SET
    nama = EXCLUDED.nama,
    tempat_lahir = EXCLUDED.tempat_lahir,
    tanggal_lahir = EXCLUDED.tanggal_lahir,
    tanggal_lahir_str = EXCLUDED.tanggal_lahir_str,
    pangkat = EXCLUDED.pangkat,
    golongan = EXCLUDED.golongan,
    tmt_golongan = EXCLUDED.tmt_golongan,
    jabatan = EXCLUDED.jabatan,
    tmt_jabatan = EXCLUDED.tmt_jabatan,
    esselon = EXCLUDED.esselon,
    pendidikan = EXCLUDED.pendidikan,
    diklat = EXCLUDED.diklat,
    status_pegawai = EXCLUDED.status_pegawai,
    kategori_pegawai = EXCLUDED.kategori_pegawai,
    bidang = EXCLUDED.bidang,
    npwp = COALESCE(EXCLUDED.npwp, public.dkpp_pegawai_nip.npwp),
    kelas_jabatan = COALESCE(EXCLUDED.kelas_jabatan, public.dkpp_pegawai_nip.kelas_jabatan),
    is_sensitive = EXCLUDED.is_sensitive,
    is_active = EXCLUDED.is_active,
    keterangan = EXCLUDED.keterangan,
    updated_at = now();

-- 5. Perbarui Fungsi RPC Verifikasi NIP
CREATE OR REPLACE FUNCTION public.verify_dkpp_nip(input_nip TEXT)
RETURNS TABLE (
    valid BOOLEAN,
    nama VARCHAR,
    jabatan VARCHAR,
    bidang VARCHAR,
    status_pegawai VARCHAR,
    keterangan TEXT
) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY
    SELECT true, p.nama, p.jabatan, p.bidang, p.status_pegawai, p.keterangan
    FROM public.dkpp_pegawai_nip p
    WHERE REPLACE(p.nip, ' ', '') = REPLACE(TRIM(input_nip), ' ', '') AND p.is_active = true
    LIMIT 1;
END;
$$;